def reload_contract(contract):
    return {'type': 'ir.actions.act_window', 'name': contract.x_name or 'عقد العمل', 'res_model': 'x_hr.applicant_employment_contract', 'res_id': contract.id, 'view_mode': 'form', 'views': [(False, 'form')], 'target': 'current'}


def selection_allows(record_or_model, field_name, value):
    if field_name not in record_or_model._fields:
        return False
    selection = record_or_model._fields[field_name].selection
    if not selection:
        return True
    allowed = []
    for item in selection:
        if isinstance(item, (list, tuple)) and item:
            allowed.append(item[0])
    return value in allowed


def append_note(registry, line):
    if registry and 'x_notes' in registry._fields:
        existing = registry.x_notes or ''
        registry.sudo().write({'x_notes': (existing + '\n' + line).strip() if existing else line})


def sync_registry_printed(contract):
    registry = contract.x_recruitment_document_id.sudo() if contract.x_recruitment_document_id else False
    if not registry:
        return False
    vals = {}
    if selection_allows(registry, 'x_state', 'signature_requested'):
        vals['x_state'] = 'signature_requested'
    if selection_allows(registry, 'x_signature_mode', 'manual_attachment'):
        vals['x_signature_mode'] = 'manual_attachment'
    if 'x_sent_on' in registry._fields:
        vals['x_sent_on'] = datetime.datetime.now()
    if 'x_responsible_user_id' in registry._fields:
        vals['x_responsible_user_id'] = env.user.id
    if vals:
        registry.write(vals)
    append_note(registry, 'تم اعتماد طباعة عقد العمل وبدء مسار التوقيع اليدوي خارج Odoo Sign.')
    return registry


