def attach_to_applicant(attachment, applicant):
    # Do not retarget ir.attachment here.
    # In Odoo Enterprise Documents, the uploaded attachment may already have a
    # documents.document row. Rewriting res_model/res_id can make Documents try
    # to create another documents.document for the same attachment_id, causing:
    # documents_document_attachment_unique.
    #
    # Keep linkage through:
    # - contract.x_signed_attachment_id / x_ministry_accredited_attachment_id
    # - x_hr.recruitment_document existing attachment fields where available
    # - applicant chatter note / already-uploaded applicant file
    return False


def sync_registry_signed(contract, attachment):
    registry = contract.x_recruitment_document_id.sudo() if contract.x_recruitment_document_id else False
    if not registry:
        return False
    now = datetime.datetime.now()
    vals = {}
    if selection_allows(registry, 'x_state', 'signed'):
        vals['x_state'] = 'signed'
    if selection_allows(registry, 'x_signature_mode', 'manual_attachment'):
        vals['x_signature_mode'] = 'manual_attachment'
    if 'x_signed_attachment_id' in registry._fields:
        vals['x_signed_attachment_id'] = attachment.id
    if 'x_signed_on' in registry._fields:
        vals['x_signed_on'] = now
    if 'x_sign_completed_on' in registry._fields:
        vals['x_sign_completed_on'] = now
    if 'x_sign_completed_attachment_id' in registry._fields:
        vals['x_sign_completed_attachment_id'] = attachment.id
    if 'x_responsible_user_id' in registry._fields:
        vals['x_responsible_user_id'] = env.user.id
    if vals:
        registry.write(vals)
    append_note(registry, 'تم تثبيت النسخة الموقعة يدوياً من عقد العمل. يبقى انتقال مرحلة الترحيل النهائية مشروطاً باستكمال قرار التعيين وTOR وF-0007 وF-0009.')
    return registry


