def sync_applicant_notes(contract):
    applicant = contract.x_applicant_id.sudo() if contract.x_applicant_id else False
    if not applicant:
        return
    vals = {}
    if 'x_employment_contract_state' in applicant._fields:
        vals['x_employment_contract_state'] = contract.x_state or False
    if 'x_employment_contract_notes' in applicant._fields:
        vals['x_employment_contract_notes'] = contract.x_handover_blocking_notes or False
    if vals:
        applicant.write(vals)


def signed_doc_map(applicant):
    result = {}
    if not applicant:
        return result

    Document = env['x_hr.recruitment_document'].sudo()
    docs = Document.search([
        ('x_applicant_id', '=', applicant.id),
        ('x_state', '=', 'signed'),
        ('x_document_type', 'in', [
            'board_decision',
            'employment_contract',
            'tor',
            'policies_compliance_declaration',
            'non_disclosure_agreement',
        ]),
    ])

    for doc in docs:
        dtype = doc.x_document_type
        if dtype and dtype not in result:
            result[dtype] = doc

    return result


contract = records.sudo()[:1]

if not contract:
    action = toast('لا يوجد عقد', 'افتح سجل عقد أولاً.', 'warning')
else:
    applicant = contract.x_applicant_id.sudo() if contract.x_applicant_id else False

    labels = {
        'board_decision': 'قرار التعيين',
        'employment_contract': 'عقد العمل',
        'tor': 'TOR / F-0006',
        'policies_compliance_declaration': 'F-0007 إقرار السياسات والإجراءات',
        'non_disclosure_agreement': 'F-0009 اتفاقية عدم الإفصاح',
    }

    required = [
        'board_decision',
        'employment_contract',
        'tor',
        'policies_compliance_declaration',
        'non_disclosure_agreement',
    ]

    signed = signed_doc_map(applicant)
    missing = []

    for dtype in required:
        if dtype not in signed:
            missing.append(labels[dtype])

    if contract.x_state != 'ministry_accredited' or not contract.x_ministry_accredited_attachment_id:
        missing.append('اعتماد وزارة العمل لعقد العمل')

    if missing:
        note = 'بوابة الترحيل غير مكتملة. المتبقي: %s.' % '، '.join(missing)
        contract.write({
            'x_handover_state': 'blocked',
            'x_handover_ready': False,
            'x_handover_blocking_notes': note,
        })
        sync_applicant_notes(contract)
        action = toast('بوابة الترحيل غير مكتملة', note, 'warning', False, reload_contract(contract))
    else:
        contract.write({
            'x_handover_state': 'ready',
            'x_handover_ready': True,
            'x_handover_blocking_notes': False,
        })
        sync_applicant_notes(contract)
        action = toast(
            'جاهز للترحيل',
            'اكتملت مستندات preboarding المطلوبة وأصبح العقد جاهزاً لمرحلة الترحيل اللاحقة.',
            'success',
            False,
            reload_contract(contract)
        )
